// Converts the ElderGuard DTCG token files (exported from Figma) into a typed
// TypeScript module that both the web app and the mobile app import.
//
// Run with: npm run tokens -w shared
// Source files: shared/tokens/*.tokens.json  (replace them when the design system changes)
// Output:       shared/src/tokens/tokens.generated.ts  (do not edit by hand)

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const read = (name) => JSON.parse(readFileSync(join(root, 'tokens', name), 'utf8'));

const camel = (s) => s.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());

/** Flattens a DTCG tree into { 'a.b.c': token } */
function flatten(node, path = [], out = {}) {
  if (node && typeof node === 'object' && '$value' in node) {
    out[path.join('.')] = node;
    return out;
  }
  for (const [key, child] of Object.entries(node ?? {})) {
    if (key.startsWith('$')) continue;
    flatten(child, [...path, key], out);
  }
  return out;
}

function resolveValue(value, flat, seen = new Set()) {
  if (typeof value === 'string') {
    const ref = /^\{([^}]+)\}$/.exec(value);
    if (!ref) return value;
    const target = ref[1];
    if (seen.has(target)) throw new Error(`Circular token reference: ${target}`);
    const token = flat[target];
    if (!token) throw new Error(`Unknown token reference: {${target}}`);
    return resolveValue(token.$value, flat, new Set([...seen, target]));
  }
  if (value && typeof value === 'object') {
    if (typeof value.hex === 'string') return value.hex; // DTCG 2025 color object
    if ('value' in value && 'unit' in value) return value.value; // dimension -> number of px
  }
  return value;
}

/** Builds a nested object for the given top-level groups, resolving every alias. */
function build(file, groups) {
  const flat = flatten(file);
  const out = {};
  for (const [path, token] of Object.entries(flat)) {
    const [group, ...rest] = path.split('.');
    if (!groups.includes(group)) continue;
    let cursor = (out[group] ??= {});
    rest.forEach((part, i) => {
      const key = camel(part);
      if (i === rest.length - 1) {
        let v = resolveValue(token.$value, flat);
        if (typeof v === 'string' && v.startsWith('#')) v = v.toLowerCase();
        cursor[key] = v;
      } else {
        cursor = cursor[key] ??= {};
      }
    });
  }
  return out;
}

const colorGroups = ['sys', 'status', 'chart', 'comp'];
const light = build(read('Color.Light.tokens.json'), colorGroups);
const dark = build(read('Color.Dark.tokens.json'), colorGroups);
const numbers = build(read('Numbers.Default.tokens.json'), [
  'spacing',
  'radius',
  'size',
  'layout',
  'opacity',
]);

// Light and dark must expose exactly the same keys, or night mode will break.
const keys = (o, p = '') =>
  Object.entries(o).flatMap(([k, v]) => (v && typeof v === 'object' ? keys(v, `${p}${k}.`) : [`${p}${k}`]));
const lk = new Set(keys(light));
const dk = new Set(keys(dark));
const missing = [...lk].filter((k) => !dk.has(k)).concat([...dk].filter((k) => !lk.has(k)));
if (missing.length) throw new Error(`Light/Dark token mismatch: ${missing.join(', ')}`);

const banner = `// AUTO-GENERATED by shared/scripts/build-tokens.mjs from shared/tokens/*.tokens.json.
// Do not edit by hand. Run \`npm run tokens -w shared\` after replacing the token files.
`;
const body = `${banner}
export const lightColors = ${JSON.stringify(light, null, 2)} as const;

export const darkColors = ${JSON.stringify(dark, null, 2)} as const;

export const numbers = ${JSON.stringify(numbers, null, 2)} as const;
`;

const outFile = join(root, 'src', 'tokens', 'tokens.generated.ts');
mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, body);
console.log(`Wrote ${outFile} (${lk.size} color tokens per mode)`);
